class Solution {public int solve(int[] a){int n=a.length;if(n==0)return 0;int[] len=new int[n],ways=new int[n];java.util.Arrays.fill(len,1);java.util.Arrays.fill(ways,1);int best=1;for(int i=0;i<n;i++){for(int j=0;j<i;j++)if(a[j]<a[i]){if(len[j]+1>len[i]){len[i]=len[j]+1;ways[i]=ways[j];}else if(len[j]+1==len[i])ways[i]=(ways[i]+ways[j])%1000000007;}best=Math.max(best,len[i]);}int answer=0;for(int i=0;i<n;i++)if(len[i]==best)answer=(answer+ways[i])%1000000007;return answer;}}